#!/usr/bin/env python3
"""Render accessible static lessons and a local search index from versioned inputs."""
import argparse,html,json,re
from pathlib import Path
from education_widgets import widgets_for, client_definitions, WIDGETS
ROOT=Path(__file__).resolve().parents[1]
def esc(s):return html.escape(str(s),quote=True)
def text(s):return html.unescape(re.sub('<[^>]+>',' ',s)).strip()
def load(name):return json.loads((ROOT/'assets/data'/name).read_text())
def icon(kind):
 paths={'spectrum':'M3 20 Q8 0 13 20 T23 20 M30 4 V28 M36 8 V24 M42 4 V28','atom':'M5 25 H43 M5 8 H43 M24 8 V25 M20 12 L24 8 L28 12','transfer':'M4 8 H18 M4 16 H18 M4 24 H18 M23 3 V29 M29 8 H44 M29 16 H38 M29 24 H44','workflow':'M3 8 H13 V24 H3 Z M20 8 H30 V24 H20 Z M37 8 H47 V24 H37 Z M13 16 H20 M30 16 H37','transit':'M17 16 A10 10 0 1 0 17 16.1 M32 16 A4 4 0 1 0 32 16.1 M2 29 H46','provenance':'M4 6 H17 V15 H4 Z M31 6 H44 V15 H31 Z M17 25 H31 M10 15 V25 H38 V15','journey':'M3 7 H45 M3 16 H45 M3 25 H45 M11 3 V29 M24 3 V29 M37 3 V29'}
 return f'<svg viewBox="0 0 50 32" aria-hidden="true"><path d="{paths[kind]}"/></svg>'
def diagram(kind):
 diagrams={
 'spectrum':('Shorter wavelength → higher photon energy','UV → visible → IR','An arrow orders wavelength; band edges are conventions.'),
 'atom':('Higher energy state','↓ emission · ↑ absorption','Photon energy equals the gap; spacing is schematic.'),
 'transfer':('Continuum from deeper layers','Atmosphere → emergent spectrum','Opacity and emission both matter along the light path.'),
 'workflow':('Calibrated spectrum → line model','Abundance → uncertainty → review','Every inference preserves source and model provenance.'),
 'transit':('Starlight → planet crossing','A brightness dip → radius ratio','Uniform-disk approximation; geometry is not chemistry.'),
 'provenance':('Experiment / theory → source','Evaluated data → line use → validation','A database entry does not make theory experimental.'),
 'journey':('Light → atom → stellar spectrum','Abundance → planetary interpretation','Separate observations, assumptions and interpretation.')}
 a,b,c=diagrams[kind]
 return f'<figure class="lesson-figure"><div class="diagram-icon">{icon(kind)}</div><div><p>{esc(a)}</p><p>{esc(b)}</p></div><figcaption>{esc(c)}</figcaption></figure>'
def explorer(d):
 lo=next(x for x in d['levels'] if x['id']=='2s');hi=next(x for x in d['levels'] if x['id']=='3p');delta=hi['energy_cm1']-lo['energy_cm1'];nm=1e7/delta;e=d['constants']['h_J_s']*d['constants']['c_m_s']*100*delta/d['constants']['e_C']
 options=''.join(f'<option value="{t["id"]}"'+(' selected' if t['id']=='balmer-alpha' else '')+'>'+esc(t['label'])+'</option>' for t in d['transitions'])
 return f'''<section id="hydrogen-explorer" class="explorer" aria-labelledby="explorer-title">
 <div class="section-label">Interactive 01 // energy conservation</div><h3 id="explorer-title">Atomic transition explorer · hydrogen &amp; sodium</h3>
 <p>Choose a fine-structure component. Read the states, photon and spectral line together.</p>
 <p id="explorer-load" role="status">Static reference view: Balmer α emission. Interactive controls require JavaScript and the local reference file.</p>
 <form id="transition-controls" hidden><div class="control-grid"><label>Atom<select id="atom"><option value="H">Hydrogen (H I)</option><option value="Na">Neutral sodium (Na I)</option></select></label><label>Reference transition<select id="transition">{options}</select></label></div>
 <fieldset><legend>Interaction</legend><label><input type="radio" name="mode" value="emission" checked> Emission · higher → lower</label><label><input type="radio" name="mode" value="absorption"> Absorption · lower → higher</label></fieldset>
 <div class="actions"><button type="button" id="play-transition">Play once</button><button type="reset">Reset reference</button><button type="button" id="download-transition">Download labeled CSV</button><button type="button" id="download-diagram">Download diagram SVG</button></div></form>
 <figure class="transition-figure" tabindex="0" aria-label="Atomic energy levels; scroll horizontally on small screens"><svg id="transition-diagram" viewBox="0 0 560 290" role="img" aria-labelledby="transition-title transition-desc" xmlns="http://www.w3.org/2000/svg">
 <title id="transition-title">Hydrogen Balmer α emission</title><desc id="transition-desc">An electron drops from the upper state to the lower state, emitting one photon. Vertical spacing is schematic.</desc>
 <defs><marker id="arrowhead" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto-start-reverse"><path d="M0 0 L8 4 L0 8 Z" fill="#4fc3f7"/></marker></defs>
 <path class="level" d="M40 70 H310 M40 215 H310"/><text x="40" y="45" id="upper-label">{esc(hi['label'])} · {hi['energy_cm1']:.4f} cm⁻¹</text><text x="40" y="246" id="lower-label">{esc(lo['label'])} · {lo['energy_cm1']:.4f} cm⁻¹</text>
 <path id="transition-arrow" d="M190 85 V200" marker-end="url(#arrowhead)"/><circle id="electron" cx="150" cy="70" r="8"/><circle id="photon" cx="360" cy="140" r="7"/><text x="330" y="110">Photon</text><text x="325" y="180" id="photon-label">{e:.3f} eV</text><text x="40" y="280">Energy ↑ · schematic spacing, not to scale</text>
 </svg><figcaption id="transition-caption">Emission: {esc(hi['label'])} → {esc(lo['label'])}. A photon carries the energy difference. Electron markers show states, not orbits.</figcaption></figure>
 <p id="atomic-color-note">Photon color is schematic.</p><figure class="atomic-band-figure" tabindex="0" aria-label="Atomic spectrum; scroll horizontally on small screens"><svg id="atomic-spectrum" viewBox="0 0 720 160" role="img" aria-label="Visible-spectrum line position" xmlns="http://www.w3.org/2000/svg"><title>Static visible-spectrum reference</title><text x="40" y="80">Balmer α: {nm:.2f} nm vacuum, in the red visible band.</text></svg><svg id="atomic-doublet" viewBox="0 0 720 160" role="img" aria-label="Sodium doublet zoom" hidden xmlns="http://www.w3.org/2000/svg"></svg><figcaption>Line positions use vacuum wavelength. The top strip locates colors; the lower strip compares emission on darkness with absorption in a continuum. Width and brightness are illustrative.</figcaption></figure><dl class="readouts"><div><dt>Vacuum wavelength</dt><dd id="wavelength">{nm:.2f} nm</dd></div><div><dt>Photon energy</dt><dd id="photon-energy">{e:.3f} eV</dd></div><div><dt>Band</dt><dd id="transition-band">Visible</dd></div></dl>
 <figure class="spectrum-figure"><svg id="line-diagram" viewBox="0 0 560 180" role="img" aria-labelledby="line-title line-desc" xmlns="http://www.w3.org/2000/svg"><title id="line-title">Linked spectral line</title><desc id="line-desc">Illustrative emission peak at the selected transition. Width and height are arbitrary.</desc><path class="axis" d="M40 20 V135 H525"/><path id="line-profile" d="M40 120 H240 Q280 -70 320 120 H525"/><text x="50" y="25">Relative signal (schematic)</text><text x="210" y="164" id="line-label">{nm:.2f} nm · vacuum</text></svg><figcaption>Linked line position; shape, width and intensity are illustrative. UV photons have no visible color.</figcaption></figure>
 <p id="transition-status" role="status" aria-live="polite">Ready: emission starts in the upper state.</p>
 <div id="share-controls" hidden><label>Share this configuration<input id="share-configuration" readonly type="url"></label></div>
 <details><summary>Reference data, assumptions and teacher notes</summary><p>{esc(d['wavelength_convention'])}. {esc(d['uncertainty'])}</p><ul>{''.join('<li>'+esc(x)+'</li>' for x in d['assumptions'])}</ul><p>Classroom: predict the direction, play once, then reverse the mode. Does changing direction change the photon energy? Why does Balmer β have a shorter wavelength? Use the CSV to record the level identity and source.</p><p>Stellar absorption is a radiative-transfer phenomenon involving opacity, emission, scattering and populations in an atmosphere; this isolated transition does not simulate a star.</p><p>Sources: <a href="{d['sources']['nist-levels']['url']}">NIST hydrogen levels</a>, <a href="{d['sources']['nist-lines']['url']}">NIST line-component context</a>, <a href="{d['sources']['constants']['url']}">SI constants</a>. <a href="/assets/data/education-hydrogen.v1.json">Versioned hydrogen reference data</a> · <a href="/assets/data/education-sodium.v1.json">Sodium levels and canonical metadata snapshot</a> · <a href="https://physics.nist.gov/PhysRefData/Handbook/Tables/sodiumtable5.htm">NIST Na I levels</a>. The sodium D doublet connects the same lower state to two fine-structure upper states. NIST Handbook sodium line wavelengths are air values; this explorer derives vacuum Ritz estimates from the energies.</p></details>
 <noscript><p>Read the static Balmer α example above and the complete lessons below. No animation or search is needed to complete the beginner journey.</p></noscript></section>'''
def render():
 data=load('education-lessons.v1.json');hydrogen=load('education-hydrogen.v1.json');models=load('education-models.v1.json')
 base=(ROOT/'spectroscopic-frontier/index.html').read_text()
 head=base[:base.index('<main id="main">')].replace('Spectroscopic Frontier','Education &amp; Learning Center').replace('Skip to atlas','Skip to learning modules').replace('Explore atomic and molecular model resources, documented coverage, scientific limits and open research gaps.','Learn spectroscopy, atomic physics and exoplanet science with working interactive science experiments.').replace('href="https://exoplanetcodex.org/spectroscopic-frontier/"','href="https://exoplanetcodex.org/education/"').replace('/assets/css/frontier-atlas.css','/assets/css/education.css').replace('  <script src="/assets/js/analytics.js"></script>\n','').replace('<canvas id="starfield" aria-hidden="true"></canvas>','')
 head=head.replace(' class="active" aria-current="page"','').replace('<a href="/education/">Education</a>','<a href="/education/" class="active" aria-current="page">Education</a>')
 footer=base[base.index('  <footer class="codex-footer">'):base.index('<script src="/assets/js/starfield.js">')]
 contents=['<main id="main"><header class="education-intro"><div class="page-eyebrow">Education // an open learning environment</div><h1>From light to <em>other worlds.</em></h1><p>Explore the physics behind a spectrum, follow the evidence to a stellar abundance, and learn what it can tell us about planets.</p><p class="review-state">Source-checked draft · independent scientific and accessibility review pending</p></header>']
 contents.append('<nav class="module-grid" aria-label="Learning modules">'+''.join(f'<a class="module-tile" href="#{l["id"]}">{icon(l["diagram"])}<span class="module-number">0{i+1}</span><strong>{esc(l["title"])}</strong><span>{esc(l["description"])}</span><span class="tile-go">{sum(1 for w in WIDGETS if w["module"]==l["id"])+(1 if l["id"]=="atomic-physics" else 0)} working experiments →</span></a>' for i,l in enumerate(data['lessons']))+'</nav>')
 contents.append('''<section class="education-search" aria-labelledby="search-title"><h2 id="search-title">Find a concept</h2><form id="education-search-form" role="search" hidden><label for="education-query">Search Education, Glossary &amp; Methodology</label><input id="education-query" type="search" placeholder="Try Teff, photon energy, microturbulence…" autocomplete="off" aria-describedby="search-help"><p id="search-help">Titles and concepts, with aliases and close spellings. Results are links to authored content.</p><p id="search-status" role="status" aria-live="polite"></p><ol id="search-results"></ol></form><p id="search-load">Browse the module tiles, <a href="/glossary/">Glossary definitions</a> or <a href="/method/">Codex Methodology</a>. Search loads a local index when JavaScript is available.</p></section><aside class="journey"><strong>Your first journey</strong><p><a href="#light">Light</a> → <a href="#atomic-physics">Spectral lines</a> → <a href="#stellar-spectroscopy">Stellar spectrum</a> → <a href="#elemental-abundances">Elemental abundance</a> → <a href="#exoplanets">Exoplanet interpretation</a></p><p>Definitions live in the <a href="/glossary/">Glossary</a>; documented project practices live in <a href="/method/">Methodology</a>. Explore ideas here.</p></aside>''')
 # Keep search within the top navigation area even on narrow screens.
 search,journey=contents[2].split('<aside',1)
 contents=[contents[0],search,contents[1],'<aside'+journey]
 index=[]
 for i,l in enumerate(data['lessons']):
  contents.append(f'<section class="lesson" id="{l["id"]}" aria-labelledby="{l["id"]}-title"><div class="section-label">Module 0{i+1} // learn &amp; explore</div><h2 id="{l["id"]}-title">{esc(l["title"])}</h2><p class="lesson-deck">{esc(l["description"])}</p><div class="objectives"><h3>What you will learn</h3><ul>'+''.join('<li>'+esc(x)+'</li>' for x in l['objectives'])+'</ul></div>')
  if l['id']=='atomic-physics':contents.append(explorer(hydrogen))
  contents.append(widgets_for(l['id'],models))
  contents.append('<div class="lesson-copy"><h3>Start here</h3><p>'+esc(l['beginner'])+'</p>'+diagram(l['diagram'])+'<details><summary>Go deeper · the mathematics</summary><p>'+esc(l['mathematics'])+'</p></details><details><summary>Advanced · assumptions and scientific limits</summary><p>'+esc(l['advanced'])+'</p></details></div>')
  contents.append('<div class="example-grid"><article><h3>Worked example / activity</h3><p>'+esc(l['example'])+'</p></article><article><h3>Common misconception</h3><p>'+esc(l['misconception'])+'</p></article></div>')
  if l['id']=='atomic-laboratory':contents.append('<p><a href="/roadmap.html#atomic-laboratory">Atomic Laboratory development and validation gates</a> · <a href="/spectroscopic-frontier/">Atomic &amp; Molecular Model Atlas</a> · <a href="/sources/#roadmap-software">Software and literature sources</a></p>')
  if l['id']=='learning-resources':contents.append('<p><a href="/education/classroom-activity.txt" download>Download classroom activity and answer guide (text)</a> · <a href="#learning-roadmap">Learning content roadmap</a></p>')
  contents.append('<div class="lesson-links"><p>Definitions: '+ ' · '.join(f'<a href="/glossary/#{t}">{esc(t.replace("-"," "))}</a>' for t in l['glossary'])+f'</p><p>Project practice: <a href="/method/#{l["method"]}">Methodology — {esc(l["method"])}</a></p></div>')
  contents.append('<details class="lesson-sources"><summary>Sources and review record</summary><ul>'+''.join(f'<li><a href="{esc(data["sources"][k]["url"])}">{esc(data["sources"][k]["title"])}</a></li>' for k in l['sources'])+f'</ul><p>Last source check: <time>{l["last_source_check"]}</time>. Independent scientific reviewer: pending. Accessibility reviewer: pending. This date records source checking, not independent approval.</p></details>')
  nxt=data['lessons'][(i+1)%len(data['lessons'])];contents.append(f'<p class="lesson-next"><a href="#{nxt["id"]}">Next: {esc(nxt["title"])} →</a> · <a href="#main">Back to modules ↑</a></p></section>')
  index.append({'title':l['title'],'description':l['description'],'concepts':' '.join([l['beginner'],l['mathematics'],l['advanced']]),'url':'/education/#'+l['id'],'type':'Lesson'})
 contents.append('''<section class="lesson" id="learning-roadmap"><div class="section-label">Build with evidence</div><h2>More ways to explore</h2><p>Working lessons: light and color, prism/grating dispersion, resolution and Doppler shift; H/Na atomic transitions; a schematic stellar slab; EW and curve of growth; transit and stellar RV; atomic metadata; an interactive assessment. Scientific and accessibility review is pending.</p><p>Future extensions: validated stellar-atmosphere grids, Planck continuum, explicit multi-line blends, rotational/macroturbulent broadening and fitted observations. The current stellar control panel is an explicitly schematic absorbing slab, not a grid prediction.</p><p>Future research integrations: independently validated theoretical Atomic Laboratory candidates and advanced 3D NLTE exercises. Current metadata is pinned to cited canonical records; unknown and ungraded quantities remain explicit.</p><p>Lessons, GUIs, classroom exercises and downloads remain free without subscriptions or registration. Illustrations are original code-drawn diagrams. Proposed reuse license: CC BY 4.0 for original educational text and figures, subject to owner approval; no new license grant is made by this draft. Linked sources retain their own terms.</p><p><a href="/roadmap.html">Project roadmap and evidence</a> · <a href="/sources/">Project bibliography</a> · <a href="https://github.com/damienabraxas/exoplanetcodex-site/issues/new">Suggest an educational correction</a></p></section></main>''')
 index.append({'title':'Atomic transition explorer: hydrogen and sodium','description':'Emission, absorption, photon energy and vacuum wavelength; downloadable CSV, SVG and shareable configurations.','concepts':'hydrogen sodium doublet balmer lyman atomic transition simulator electron','url':'/education/#hydrogen-explorer','type':'Interactive'})
 for w in WIDGETS:
  index.append({'title':w['title'],'description':w['caption'],'concepts':w['notes']+' '+w['teacher'],'url':'/education/#'+w['id'],'type':'Interactive'})
 gloss=(ROOT/'glossary/index.html').read_text()
 for match in re.finditer(r'<div class="term-card" id="([^"]+)">(.*?)(?=<div class="term-card"|<section class="gloss-section"|</main>)',gloss,re.S):
  term,body=match.groups();title=re.search(r'<h3[^>]*>(.*?)</h3>',body,re.S)
  if title:index.append({'title':text(title[1]),'description':'Definition in the existing Glossary.','concepts':text(body)[:1500],'url':'/glossary/#'+term,'type':'Glossary'})
 method=(ROOT/'method/index.html').read_text()
 for match in re.finditer(r'<section[^>]+id="([^"]+)"[^>]*>(.*?)(?=</section>)',method,re.S):
  id,body=match.groups();title=re.search(r'<h2[^>]*>(.*?)</h2>',body,re.S)
  if title:index.append({'title':text(title[1]),'description':'Documented Codex practices in Methodology.','concepts':text(body)[:2000],'url':'/method/#'+id,'type':'Methodology'})
 return {'assets/data/education-widgets.v1.json':json.dumps({'schema_version':1,'widgets':client_definitions()},indent=2,ensure_ascii=False)+'\n','education/index.html':head+'\n'.join(contents)+footer+'<script type="module" src="/assets/js/education.js"></script><script type="module" src="/assets/js/education-simulators.js"></script></body></html>\n','assets/data/education-search.v1.json':json.dumps({'schema_version':1,'entries':index},indent=2,ensure_ascii=False)+'\n'}
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args();stale=[]
 for name,value in render().items():
  path=ROOT/name
  if not path.exists() or path.read_text()!=value:
   stale.append(name)
   if not a.check:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(value)
 if a.check and stale:raise SystemExit('Stale Education outputs: '+', '.join(stale))
 print('Education generated outputs: PASS' if a.check else 'Rendered Education page and local search index')
